test('a text message longer than 160 characters keeps its first 157 characters and ends in "..."', () => {
  const title = 'A very long title '.repeat(10).trim();
  const values = { title, branch: 'Central', deadline: '2026-12-01' };
  const sms = composeNotice('holdReady', { member: BEN, values });
  assert.equal(sms.body.length, 160);
  assert.ok(sms.body.endsWith('...'));
  const email = composeNotice('holdReady', { member: ADA, values });
  assert.ok(email.body.length > 160);
  assert.ok(email.body.includes(title));
  assert.equal(sms.body.slice(0, 157), email.body.slice(0, 157));
});

test('a text message of 160 characters or fewer is left as it is', () => {
  const notice = composeNotice('dueSoon', { member: BEN, values: { title: DVD.title, dueOn: '2026-11-27' } });
  assert.ok(notice.body.length <= 160);
  assert.ok(!notice.body.endsWith('...'));
});

